import {STATUSES} from './model.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function shopBoard(parts,dateLabel){
 return `<div class="shop-board">${STATUSES.map((stage,index)=>{
  const rows=parts.filter(p=>p.status===stage).sort((a,b)=>Number(b.blocked)-Number(a.blocked)||Number(b.priority==='High')-Number(a.priority==='High')||(a.due||'9999').localeCompare(b.due||'9999'));
  const next=STATUSES[index+1];
  return `<section class="shop-lane lane-${index}"><h3>${stage}<span>${rows.length}</span></h3><div class="shop-lane-cards">${rows.length?rows.map(p=>`<article class="shop-card ${p.blocked?'is-blocked':''}"><div class="shop-card-top"><span>${escape(p.number||'No part number')}</span>${p.blocked?'<strong class="blocked-tag">⚑ Blocked</strong>':''}${p.priority==='High'?'<strong>HIGH PRIORITY</strong>':''}</div><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="shop-card-meta"><strong>${escape(p.owner||p.assignedTo||'Unassigned')}</strong><span>Qty ${p.quantity} · ${escape(p.subsystem||'No subsystem')}</span><span>${escape(p.process||'No process assigned')}</span><span>Due ${escape(dateLabel(p.due))}</span></div>${p.blocked&&p.notes?`<p class="shop-note">${escape(p.notes)}</p>`:''}<label class="shop-status-label">Manufacturing stage<select data-status="${escape(p.id)}" aria-label="Stage for ${escape(p.name)}">${STATUSES.map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label>${next?`<button class="shop-action" data-advance="${escape(p.id)}" data-next="${next}">${index===0?'▶ Start preparing':next==='Finished'?'✓ Mark finished':'Move to '+next.toLowerCase()}</button>`:'<div class="finished-label">✓ Manufacturing finished</div>'}<button class="block-toggle ${p.blocked?'tag-active':''}" aria-pressed="${Boolean(p.blocked)}" data-block="${escape(p.id)}">${p.blocked?'Remove blocked tag':'+ Tag blocked'}</button></article>`).join(''):'<p class="lane-empty">No parts in this stage</p>'}</div></section>`;
 }).join('')}</div>`;
}
